class Solution {
    public int maximumRequests(int n,int[][] requests){
        int answer=0,total=1<<requests.length;
        for(int mask=0;mask<total;mask++){
            int selected=Integer.bitCount(mask);
            if(selected<=answer)continue;
            int[] balance=new int[n];
            for(int i=0;i<requests.length;i++)if((mask&(1<<i))!=0){
                balance[requests[i][0]]--;
                balance[requests[i][1]]++;
            }
            boolean valid=true;
            for(int value:balance)if(value!=0){
                valid=false;
                break;
            }
            if(valid)answer=selected;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maximumRequests(n:Int,requests:Array<IntArray>):Int{
        var answer=0;
        for(mask in 0 until (1 shl requests.size)){
            val selected=Integer.bitCount(mask);
            if(selected<=answer)continue;
            val balance=IntArray(n);
            for(i in requests.indices)if(mask and (1 shl i)!=0){
                balance[requests[i][0]]--;
                balance[requests[i][1]]++
            };
            if(balance.all{
                it==0
            })answer=selected
        };
        return answer
    }
}

